import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    TrendingUp, Award, Target, CalendarCheck, 
    Flame, Clock, CheckCircle, Circle, ArrowRight,
    Sparkles
} from 'lucide-react';
import axios from 'axios';
import { motion } from 'framer-motion';

const Dashboard = () => {
    const { user, token } = useAuth();
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);
    const [tasks, setTasks] = useState([]);

    const targetDate = new Date(2026, 10, 30);
    const today = new Date();
    const daysRemaining = Math.max(0, Math.ceil((targetDate - today) / (1000 * 60 * 60 * 24)));

    useEffect(() => {
        if (user) {
            fetchData();
        }
    }, [user]);

    const fetchData = async () => {
        try {
            const tasksRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasksRes.data);

            const statsRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}/progress`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setStats(statsRes.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch data:', error);
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-accent-blue"></div>
            </div>
        );
    }

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted === true).length;
    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    const calculateStreak = () => {
        let streak = 0;
        const sortedTasks = [...tasks].sort((a, b) => a.day - b.day);
        for (const task of sortedTasks) {
            if (task.overallCompleted === true) {
                streak++;
            } else {
                break;
            }
        }
        return streak;
    };

    const streak = calculateStreak();

    const todayDay = new Date().getDate();
    const todayTasks = tasks.filter(t => t.day === todayDay);
    const todayCompleted = todayTasks.filter(t => t.overallCompleted === true).length;

    const weekTasks = tasks.filter(t => t.day >= 25 && t.day <= 31);
    const weekCompleted = weekTasks.filter(t => t.overallCompleted === true).length;
    const weekProgress = weekTasks.length > 0 ? Math.round((weekCompleted / weekTasks.length) * 100) : 0;

    const statsCards = [
        {
            title: 'Overall Progress',
            value: `${completionRate}%`,
            icon: TrendingUp,
            color: 'text-accent-blue',
            bg: 'bg-blue-500/10',
        },
        {
            title: 'Current Streak',
            value: `${streak} days`,
            icon: Flame,
            color: 'text-accent-orange',
            bg: 'bg-orange-500/10',
        },
        {
            title: 'Days Remaining',
            value: `${daysRemaining} days`,
            icon: Target,
            color: 'text-accent-purple',
            bg: 'bg-purple-500/10',
        },
    ];

    return (
        <div className="w-full space-y-6">
            {/* Welcome Section */}
            <motion.div 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="relative overflow-hidden rounded-2xl p-6 md:p-8 bg-gradient-main w-full"
            >
                <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full blur-3xl"></div>
                <div className="absolute bottom-0 left-0 w-48 h-48 bg-white/5 rounded-full blur-2xl"></div>
                
                <div className="relative flex flex-wrap items-start justify-between gap-4">
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold text-white mb-2">
                            👋 Welcome back, {user?.fullName?.split(' ')[0] || user?.username}!
                        </h1>
                        <p className="text-white/80 text-base md:text-lg">
                            Let's finish your tasks today! 🏆
                        </p>
                        <div className="flex flex-wrap gap-2 mt-3">
                            <span className="px-3 py-1 bg-white/20 rounded-full text-xs md:text-sm flex items-center gap-1 text-white">
                                <Flame size={14} />
                                {streak} day streak
                            </span>
                            <span className="px-3 py-1 bg-white/20 rounded-full text-xs md:text-sm flex items-center gap-1 text-white">
                                <Award size={14} />
                                {completionRate}% complete
                            </span>
                            <span className="px-3 py-1 bg-white/20 rounded-full text-xs md:text-sm flex items-center gap-1 text-white">
                                <Target size={14} />
                                {daysRemaining} days left
                            </span>
                        </div>
                    </div>
                    <div className="bg-white/20 px-4 py-2 rounded-xl text-center backdrop-blur-sm">
                        <div className="text-2xl md:text-3xl font-bold text-white">{completionRate}%</div>
                        <div className="text-xs text-white/70">Progress</div>
                    </div>
                </div>
            </motion.div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {statsCards.map((stat, index) => (
                    <motion.div
                        key={index}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: index * 0.1 }}
                        className="card-dark w-full"
                    >
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-light-secondary">{stat.title}</p>
                                <p className="text-2xl md:text-3xl font-bold text-white mt-1">{stat.value}</p>
                            </div>
                            <div className={`${stat.bg} p-3 rounded-lg`}>
                                <stat.icon className={stat.color} size={24} />
                            </div>
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* Weekly Progress and Today's Tasks */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <motion.div 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="card-dark w-full"
                >
                    <h3 className="text-lg font-semibold text-white mb-4">📊 This Week's Progress</h3>
                    <div className="space-y-4">
                        <div>
                            <div className="flex justify-between text-sm mb-1">
                                <span className="text-light-secondary">Week Progress</span>
                                <span className="font-bold text-white">{weekProgress}%</span>
                            </div>
                            <div className="w-full bg-dark-secondary rounded-full h-2.5">
                                <div 
                                    className="bg-gradient-to-r from-accent-blue to-accent-purple h-2.5 rounded-full transition-all"
                                    style={{ width: `${weekProgress}%` }}
                                />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="bg-dark-secondary rounded-lg p-3 text-center">
                                <p className="text-2xl font-bold text-accent-blue">{weekCompleted}</p>
                                <p className="text-xs text-light-muted">Tasks Done</p>
                            </div>
                            <div className="bg-dark-secondary rounded-lg p-3 text-center">
                                <p className="text-2xl font-bold text-accent-purple">{weekTasks.length}</p>
                                <p className="text-xs text-light-muted">Total Tasks</p>
                            </div>
                        </div>
                        <div className="bg-dark-secondary rounded-lg p-3 text-center">
                            <p className="text-sm text-light-secondary">Days Remaining</p>
                            <p className="text-2xl font-bold text-accent-orange">{daysRemaining} days</p>
                            <p className="text-xs text-light-muted">Until November 30, 2026</p>
                        </div>
                    </div>
                </motion.div>

                <motion.div 
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="card-dark w-full"
                >
                    <div className="flex items-center justify-between mb-4">
                        <h3 className="text-lg font-semibold text-white">✅ Today's Tasks</h3>
                        <span className="text-xs text-light-muted">{todayCompleted}/{todayTasks.length} done</span>
                    </div>
                    {todayTasks.length > 0 ? (
                        <div className="space-y-2">
                            {todayTasks.slice(0, 4).map((task, idx) => {
                                const labels = ['Java', 'LeetCode', 'DSA', 'SQL', 'Project', 'GitHub'];
                                const statuses = [task.javaCompleted, task.leetcodeCompleted, task.dsaCompleted, task.sqlCompleted, task.projectCompleted, task.githubCompleted];
                                return (
                                    <div key={idx} className="flex items-center gap-3 p-2 rounded-lg bg-dark-secondary/50">
                                        {statuses[idx] ? 
                                            <CheckCircle size={18} className="text-accent-green flex-shrink-0" /> : 
                                            <Circle size={18} className="text-light-muted flex-shrink-0" />
                                        }
                                        <span className={`text-sm ${statuses[idx] ? 'text-light-muted line-through' : 'text-light-secondary'}`}>
                                            {labels[idx]}
                                        </span>
                                    </div>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="text-center py-8 text-light-muted">
                            <p className="text-sm">No tasks for today</p>
                            <p className="text-xs">Click on a day in the tracker to start</p>
                        </div>
                    )}
                    <button 
                        onClick={() => window.location.href = '/tracker'}
                        className="mt-4 text-accent-blue text-sm hover:text-accent-purple transition flex items-center gap-1"
                    >
                        View all tasks <ArrowRight size={16} />
                    </button>
                </motion.div>
            </div>

            {/* Quick Actions */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-gradient-to-r from-blue-600 to-blue-500 rounded-xl p-6 text-white hover:shadow-lg transition">
                    <h4 className="text-lg font-semibold mb-1">📝 Log Today</h4>
                    <p className="text-blue-100 text-sm md:text-base mb-3">Track your daily progress</p>
                    <button 
                        onClick={() => window.location.href = '/tracker'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition"
                    >
                        Go to Tracker →
                    </button>
                </div>
                <div className="bg-gradient-to-r from-purple-600 to-purple-500 rounded-xl p-6 text-white hover:shadow-lg transition">
                    <h4 className="text-lg font-semibold mb-1">📚 Roadmap</h4>
                    <p className="text-purple-100 text-sm md:text-base mb-3">View your 4-month plan</p>
                    <button 
                        onClick={() => window.location.href = '/weekly-focus'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition"
                    >
                        View Roadmap →
                    </button>
                </div>
                <div className="bg-gradient-to-r from-green-600 to-green-500 rounded-xl p-6 text-white hover:shadow-lg transition">
                    <h4 className="text-lg font-semibold mb-1">📊 Analytics</h4>
                    <p className="text-green-100 text-sm md:text-base mb-3">Detailed progress stats</p>
                    <button 
                        onClick={() => window.location.href = '/progress'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition"
                    >
                        View Analytics →
                    </button>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
